//! The protocol's Rust types, generated by typify from the manifest's schemas: the API's annotated as UniFFI records
//! and enums, and the ones only the core reads in a private `wire` module.

use std::collections::BTreeMap;

use proc_macro2::TokenStream;
use quote::quote;
use serde_json::{Map, Value};
use typify::{TypeSpace, TypeSpaceSettings};

use crate::manifest::Manifest;

pub struct Types {
    pub tokens: TokenStream,
    /// Each event's payload type, in the manifest's order.
    pub payloads: Vec<TokenStream>,
    /// Each command's input, output and refusal types, in the manifest's order.
    pub commands: Vec<[TokenStream; 3]>,
}

pub fn generate(manifest: &Manifest) -> Result<Types, String> {
    let mut roots = Roots::default();
    roots.add(&manifest.options);
    roots.add(&manifest.handshake_error);
    let payloads: Vec<_> = manifest
        .events
        .iter()
        .map(|event| roots.add(&event.payload))
        .collect();
    let commands: Vec<_> = manifest
        .commands
        .iter()
        .map(|command| {
            [
                roots.add(&command.input),
                roots.add(&command.output),
                roots.add(&command.refusal),
            ]
        })
        .collect();
    let (api, idents) = roots.generate(&manifest.defs, true)?;

    let mut wire = Roots::default();
    wire.add(&manifest.capabilities);
    wire.add(&manifest.error_frame);
    let (wire, _) = wire.generate(&manifest.defs, false)?;

    Ok(Types {
        tokens: quote! {
            #api
            pub(crate) mod wire {
                #wire
            }
        },
        payloads: payloads.iter().map(|&i| idents[i].clone()).collect(),
        commands: commands
            .iter()
            .map(|command| command.map(|i| idents[i].clone()))
            .collect(),
    })
}

/// The schemas to generate types for, each named by its `title`.
#[derive(Default)]
struct Roots(Vec<Value>);

impl Roots {
    /// Adds `schema` and returns its index.
    fn add(&mut self, schema: &Value) -> usize {
        let mut root = schema.clone();
        simplify(&mut root);
        self.0.push(root);
        self.0.len() - 1
    }

    /// The generated types, and the Rust type of each root by index. Of `defs`, only those the roots refer to become
    /// types. `exported` annotates them for UniFFI.
    fn generate(
        &self,
        defs: &Map<String, Value>,
        exported: bool,
    ) -> Result<(TokenStream, Vec<TokenStream>), String> {
        let mut settings = TypeSpaceSettings::default();
        settings
            .with_struct_builder(false)
            .with_derive("PartialEq".into());
        let mut space = TypeSpace::new(&settings);

        let defs = referenced(defs, &self.0)?
            .into_iter()
            .map(|(name, schema)| {
                let mut schema = schema.clone();
                simplify(&mut schema);
                Ok((
                    name.clone(),
                    serde_json::from_value(schema).map_err(|e| e.to_string())?,
                ))
            })
            .collect::<Result<Vec<_>, String>>()?;
        space.add_ref_types(defs).map_err(|e| e.to_string())?;

        let mut idents = Vec::new();
        for root in &self.0 {
            let name = root["title"].as_str().map(str::to_owned);
            let schema: schemars::schema::Schema =
                serde_json::from_value(root.clone()).map_err(|e| e.to_string())?;
            let id = space
                .add_type_with_name(&schema, name)
                .map_err(|e| e.to_string())?;
            idents.push(space.get_type(&id).map_err(|e| e.to_string())?.ident());
        }

        let mut file: syn::File = syn::parse2(space.to_stream()).map_err(|e| e.to_string())?;
        if exported {
            for item in &mut file.items {
                match item {
                    syn::Item::Struct(item) => item
                        .attrs
                        .push(syn::parse_quote!(#[derive(::uniffi::Record)])),
                    // Manifest updates add variants, which must not break integrators' matches.
                    syn::Item::Enum(item) => item.attrs.extend([
                        syn::parse_quote!(#[derive(::uniffi::Enum)]),
                        syn::parse_quote!(#[non_exhaustive]),
                    ]),
                    _ => {}
                }
            }
        }

        Ok((quote!(#file), idents))
    }
}

/// The `defs` that `roots` refer to, directly or through other definitions.
fn referenced<'a>(
    defs: &'a Map<String, Value>,
    roots: &[Value],
) -> Result<BTreeMap<&'a String, &'a Value>, String> {
    let mut found = BTreeMap::new();
    let mut pending: Vec<String> = roots.iter().flat_map(refs).collect();
    while let Some(name) = pending.pop() {
        let Some((name, schema)) = defs.get_key_value(&name) else {
            return Err(format!("#/$defs/{name} is missing"));
        };
        if found.insert(name, schema).is_none() {
            pending.extend(refs(schema));
        }
    }
    Ok(found)
}

/// The names of the definitions `schema` refers to by `#/$defs/<name>`.
fn refs(schema: &Value) -> Vec<String> {
    match schema {
        Value::Object(map) => {
            let own = map
                .get("$ref")
                .and_then(Value::as_str)
                .and_then(|reference| reference.strip_prefix("#/$defs/"))
                .map(str::to_owned);
            own.into_iter().chain(map.values().flat_map(refs)).collect()
        }
        Value::Array(items) => items.iter().flat_map(refs).collect(),
        _ => Vec::new(),
    }
}

/// Strips what typify would turn into validating newtypes or required defaults; Simlink validates
/// and fills these in.
fn simplify(schema: &mut Value) {
    match schema {
        Value::Object(map) => {
            if let Some(Value::Object(properties)) = map.get_mut("properties") {
                properties.retain(|_, property| {
                    !(property.get("const").is_some() && property.get("default").is_some())
                });
                let kept: Vec<String> = properties.keys().cloned().collect();
                if let Some(Value::Array(required)) = map.get_mut("required") {
                    required.retain(|name| {
                        name.as_str()
                            .is_some_and(|name| kept.iter().any(|kept| kept == name))
                    });
                }
            }
            for key in [
                "minLength",
                "maxLength",
                "pattern",
                "format",
                "default",
                "$schema",
            ] {
                map.remove(key);
            }
            for (key, value) in map.iter_mut() {
                match (key.as_str(), value) {
                    // Keys here are property and definition names, never keywords to strip.
                    ("properties" | "$defs" | "patternProperties", Value::Object(schemas)) => {
                        schemas.values_mut().for_each(simplify)
                    }
                    (_, value) => simplify(value),
                }
            }
        }
        Value::Array(items) => items.iter_mut().for_each(simplify),
        _ => {}
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn simplify_strips_keywords_but_keeps_properties_named_like_them() {
        let mut schema = json!({
            "type": "object",
            "properties": {
                "format": { "type": "string", "format": "date-time" },
                "pattern": { "type": "string", "pattern": "^a$", "maxLength": 4 },
                "kind": { "type": "string", "const": "standard", "default": "standard" },
            },
            "required": ["format", "kind"],
            "$defs": { "default": { "type": "string", "minLength": 1 } },
        });
        simplify(&mut schema);

        assert_eq!(
            schema,
            json!({
                "type": "object",
                "properties": { "format": { "type": "string" }, "pattern": { "type": "string" } },
                "required": ["format"],
                "$defs": { "default": { "type": "string" } },
            })
        );
    }
}
